<!-- 文件职责 / File responsibility: 通过唯一注册表独立编辑胸背标志。 / Independently edits chest and back symbols through the sole registry. -->
<script setup lang="ts">
import StudioNumericControl from './StudioNumericControl.vue';import {CHEST_DISPLAY_MODES,type ChestDisplayMode} from '~/domain/pet-species-registry';import type {StudioControlPath} from '~/domain/studio-control-registry';import {usePetAppearanceStore} from '~/stores/pet-appearance';const store=usePetAppearanceStore();const recipe=computed(()=>store.recipe);const chest=computed(()=>recipe.value.symbols.chest);const back=computed(()=>recipe.value.symbols.back);const active=computed(()=>['symbol','hybrid'].includes(recipe.value.chestDisplay.mode));type K='scale'|'offsetX'|'offsetY'|'offsetZ'|'rotation'|'glowIntensity';const chestControls:Array<[StudioControlPath,K]>=[['symbols.chest.scale','scale'],['symbols.chest.offsetX','offsetX'],['symbols.chest.offsetY','offsetY'],['symbols.chest.offsetZ','offsetZ'],['symbols.chest.rotation','rotation'],['symbols.chest.glowIntensity','glowIntensity']];const backControls:Array<[StudioControlPath,K]>=[['symbols.back.scale','scale'],['symbols.back.offsetX','offsetX'],['symbols.back.offsetY','offsetY'],['symbols.back.offsetZ','offsetZ'],['symbols.back.rotation','rotation'],['symbols.back.glowIntensity','glowIntensity']];function setMode(e:Event){store.checkpoint();const mode=(e.target as HTMLSelectElement).value as ChestDisplayMode;recipe.value.chestDisplay.mode=mode;if(mode==='symbol'||mode==='hybrid')chest.value.enabled=true;store.markDirty()}
</script>
<template><div class="editor"><h2>胸背标志与能量核心</h2><section class="card"><h3>胸口显示</h3><label>显示模式<select :value="recipe.chestDisplay.mode" @change="setMode"><option v-for="item in CHEST_DISPLAY_MODES" :key="item.id" :value="item.id">{{item.label}}</option></select></label><template v-if="active"><label>文字<input v-model="chest.text" maxlength="3" @focus="store.checkpoint" @input="store.markDirty"></label><label>颜色<input v-model="chest.color" type="color" @focus="store.checkpoint" @input="store.markDirty"></label><StudioNumericControl v-for="[path,key] in chestControls" :key="path" :path="path" :model-value="chest[key]" @update:model-value="chest[key]=$event"/></template></section><section class="card"><h3>后背标志</h3><label class="check"><input v-model="back.enabled" type="checkbox" @focus="store.checkpoint" @change="store.markDirty">显示</label><label>文字<input v-model="back.text" maxlength="3" @focus="store.checkpoint" @input="store.markDirty"></label><label>颜色<input v-model="back.color" type="color" @focus="store.checkpoint" @input="store.markDirty"></label><StudioNumericControl v-for="[path,key] in backControls" :key="path" :path="path" :model-value="back[key]" :disabled="!back.enabled" @update:model-value="back[key]=$event"/></section></div></template>
<style scoped>.editor{display:grid;gap:12px}.editor h2,.editor h3{margin:0}.card{display:grid;gap:9px;padding:10px;border:1px solid #ffffff18;border-radius:10px;background:#ffffff08}.card label{display:grid;gap:5px;color:#bbc2dc;font-size:11px}.card input:not([type=checkbox]):not([type=color]),.card select{min-height:38px;border:1px solid #ffffff22;border-radius:9px;padding:7px;color:#fff;background:#111526}.card input[type=color]{width:100%;height:36px;border:0;background:transparent}.check{display:flex!important;align-items:center!important;gap:7px}</style>
